require_once "includes/config.php";$csrf_token=generateCsrfToken();$errors=[];$success="";$selected_role=$_POST["role"]??$_GET["role"]??"donor";if(!in_array($selected_role,["donor","recipient","hospital"],true))$selected_role="donor";
if($_SERVER["REQUEST_METHOD"]==="POST"){$token=$_POST["csrf_token"]??"";if(!verifyCsrfToken($token))$errors[]="Invalid security token. Please try again.";$full_name=trim($_POST["full_name"]??"");$hospital_name=trim($_POST["hospital_name"]??"");$email=trim($_POST["email"]??"");$phone=trim($_POST["phone"]??"");$role=$_POST["role"]??"";$password=$_POST["password"]??"";$confirm=$_POST["confirm_password"]??"";$blood=trim($_POST["blood_group"]??"");$age=trim($_POST["age"]??"");$weight=trim($_POST["weight"]??"");$city=trim($_POST["city"]??"");$address=trim($_POST["hospital_address"]??"");$license=trim($_POST["license_number"]??"");if($full_name==="")$errors[]="Full name is required.";if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]="Please enter a valid email address.";if($phone==="")$errors[]="Phone number is required.";if(!in_array($role,["donor","recipient","hospital"],true))$errors[]="Please select a valid account type.";if(strlen($password)<8)$errors[]="Password must be at least 8 characters.";if($password!==$confirm)$errors[]="Passwords do not match.";if($city==="")$errors[]="City is required.";if($role==="donor"){if(!in_array($blood,["A+","A-","B+","B-","AB+","AB-","O+","O-"],true))$errors[]="Please select a valid blood group.";if(!is_numeric($age)||$age<18||$age>100)$errors[]="Age must be between 18 and 100.";if(!is_numeric($weight)||$weight<=0)$errors[]="Please enter a valid weight.";}if($role==="hospital"){if($hospital_name==="")$errors[]="Hospital name is required.";if($address==="")$errors[]="Hospital address is required.";if($license==="")$errors[]="Hospital license number is required.";}if(!$errors){$q=mysqli_prepare($conn,"SELECT id FROM users WHERE email=? LIMIT 1");mysqli_stmt_bind_param($q,"s",$email);mysqli_stmt_execute($q);mysqli_stmt_store_result($q);if(mysqli_stmt_num_rows($q)>0)$errors[]="An account with this email already exists.";else{$hash=password_hash($password,PASSWORD_DEFAULT);$status="pending";$q=mysqli_prepare($conn,"INSERT INTO users(name,email,password,phone,role,status) VALUES(?,?,?,?,?,?)");mysqli_stmt_bind_param($q,"ssssss",$full_name,$email,$hash,$phone,$role,$status);mysqli_stmt_execute($q);$new_id=mysqli_insert_id($conn);if($role==="donor"){$q=mysqli_prepare($conn,"INSERT INTO donors(user_id,blood_group,age,weight,city) VALUES(?,?,?,?,?)");mysqli_stmt_bind_param($q,"isids",$new_id,$blood,$age,$weight,$city);mysqli_stmt_execute($q);}if($role==="hospital"){$q=mysqli_prepare($conn,"INSERT INTO hospitals(user_id,name,address,city,license_number) VALUES(?,?,?,?,?)");mysqli_stmt_bind_param($q,"issss",$new_id,$hospital_name,$address,$city,$license);mysqli_stmt_execute($q);}$success="Account created successfully! You can log in once your account is verified.";}}}
