?><main class="auth-container register-page register-page--<?= htmlspecialchars($selected_role) ?>"><section class="auth-card register-card"><?php if($success): ?><div class="success-message"><?= htmlspecialchars($success) ?></div><?php endif; ?><?php if($errors): ?><div class="error-message"><?php foreach($errors as $error): ?><p><?= htmlspecialchars($error) ?></p><?php endforeach; ?></div><?php endif; ?><?php if($selected_role!=="hospital"): ?><p class="register-eyebrow">Join BDMS</p><?php endif; ?><h1 id="register-title"><?= $selected_role==="hospital"?"Register Your Hospital":"Create your account" ?></h1><p class="register-intro">Create the account that matches how you will use the blood donation network.</p><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrf_token) ?>"><div class="form-group role-group"><label>I am registering as a...</label><div class="role-options"><input type="radio" id="role-donor" name="role" value="donor" <?= $selected_role==="donor"?"checked":"" ?>><label for="role-donor">Donor</label><input type="radio" id="role-recipient" name="role" value="recipient" <?= $selected_role==="recipient"?"checked":"" ?>><label for="role-recipient">Recipient</label><input type="radio" id="role-hospital" name="role" value="hospital" <?= $selected_role==="hospital"?"checked":"" ?>><label for="role-hospital">Hospital</label></div></div><div class="form-row"><div class="form-group"><label id="contact-name-label" for="full_name"><?= $selected_role==="hospital"?"Contact Name":"Full Name" ?></label><input id="full_name" name="full_name" required></div><div class="form-group"><label for="phone">Phone Number</label><input id="phone" name="phone" required></div></div><div class="form-group"><label>Email Address</label><input type="email" name="email" required></div><div class="form-row"><div class="form-group"><label>Password</label><input type="password" name="password" required></div><div class="form-group"><label>Confirm Password</label><input type="password" name="confirm_password" required></div></div><div id="donor-fields"><p class="role-section-title">Donor details</p><div class="form-row"><div class="form-group"><label>Blood Group</label><select id="blood_group" name="blood_group"><option value="">Select blood group</option><?php foreach(["A+","A-","B+","B-","AB+","AB-","O+","O-"] as $g): ?><option><?= $g ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Age</label><input id="age" type="number" name="age" min="18" max="100"></div></div><div class="form-group"><label>Weight (KG)</label><input id="weight" type="number" step="0.1" min="1" name="weight"></div></div><div id="hospital-fields" hidden><p class="role-section-title">Hospital details</p><div class="form-group"><label>Hospital Name</label><input id="hospital_name" name="hospital_name"></div><div class="form-group"><label>Address</label><input id="hospital_address" name="hospital_address"></div><div class="form-row"><div class="form-group"><label>City</label><input id="hospital_city" name="city"></div><div class="form-group"><label>License Number</label><input id="license_number" name="license_number"></div></div></div><div id="recipient-fields" hidden><p class="role-section-title">Recipient details</p></div><div id="city-field" class="form-group"><label>City</label><input id="city" name="city"></div><button id="register-submit" type="submit"><?= $selected_role==="hospital"?"Create Hospital Account":"Create Account" ?></button><div class="login_tag"><p>Already have an account? <a href="login.php">Log In</a></p></div></form></section></main><script>const roles=document.querySelectorAll('input[name="role"]'),donor=document.getElementById('donor-fields'),hospital=document.getElementById('hospital-fields'),recipient=document.getElementById('recipient-fields'),weight=document.getElementById('weight'),city=document.getElementById('city'),hospitalCity=document.getElementById('hospital_city'),page=document.querySelector('.register-page'),title=document.getElementById('register-title'),label=document.getElementById('contact-name-label'),submit=document.getElementById('register-submit');function update(){const r=document.querySelector('input[name="role"]:checked').value;donor.hidden=r!=='donor';hospital.hidden=r!=='hospital';recipient.hidden=r!=='recipient';document.getElementById('city-field').hidden=r==='hospital';weight.required=r==='donor';document.getElementById('blood_group').required=r==='donor';document.getElementById('age').required=r==='donor';document.getElementById('hospital_name').required=r==='hospital';document.getElementById('hospital_address').required=r==='hospital';document.getElementById('license_number').required=r==='hospital';hospitalCity.required=r==='hospital';city.required=r!=='hospital';hospitalCity.disabled=r!=='hospital';city.disabled=r==='hospital';page.className='auth-container register-page register-page--'+r;title.textContent=r==='hospital'?'Register Your Hospital':'Create your account';label.textContent=r==='hospital'?'Contact Name':'Full Name';submit.textContent=r==='hospital'?'Create Hospital Account':'Create Account'}roles.forEach(x=>x.addEventListener('change',update));update();</script><?php require "includes/public_footer.php"; ?>
